def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.55))
        return float(min(budget, DAILY_SALARY * 0.2))

    prev_bids = []
    dangerous_bids = []
    rich_threats = 0
    desperate_threats = 0

    for opp in alive_opponents:
        if opp.get('budget', 0) >= 200:
            rich_threats += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_threats += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('budget', 0) > 0:
                dangerous_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_danger = max(dangerous_bids) if dangerous_bids else highest_prev

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    base = DAILY_SALARY * (0.42 + 0.18 * scarcity)

    if supply <= 17:
        base += 8.0
    elif supply >= 23:
        base -= 5.0

    if hp <= 2 or no_water_days >= 1:
        base = max(base, DAILY_SALARY * 0.9)
    elif hp <= 4:
        base = max(base, DAILY_SALARY * 0.72)

    if highest_danger >= 120:
        if hp > 4 and no_water_days == 0 and supply >= 20:
            base = min(base, DAILY_SALARY * 0.45)
        else:
            base = max(base, DAILY_SALARY * 0.88)
    elif highest_danger >= 95:
        base = max(base, min(highest_danger + 2.0, DAILY_SALARY * 0.93))
    elif highest_danger >= 60:
        base = max(base, min(highest_danger + 1.5, DAILY_SALARY * 0.82))
    elif highest_danger > 0:
        base = max(base, highest_danger + 1.0)

    if rich_threats >= 2 and supply <= 18:
        base += 6.0
    if desperate_threats >= 1 and supply <= 19:
        base += 4.0

    if day >= 8:
        base += 4.0
    if day == 10:
        base += 6.0

    if budget < DAILY_SALARY * 1.2:
        base = min(base, budget)
    else:
        base = min(base, budget, DAILY_SALARY * 1.05)

    if base < 0:
        base = 0.0

    return float(round(base, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents alive, bid conservatively.
    if not alive_opps:
        cap = min(budget, DAILY_SALARY * 0.4)
        return max(0.0, cap)

    # Read yesterday bids from previous_trace for immediate reaction.
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate competitive pressure from yesterday.
    pressure = 0.0
    if prev_bids:
        pressure = max(prev_bids)

    # Supply factor: when supply is higher, we can bid less and still win.
    if supply >= 22.0:
        supply_factor = 0.78
    elif supply >= 18.0:
        supply_factor = 0.84
    else:
        supply_factor = 0.92

    # HP/urgency: if we're low or have accumulated no-water days, increase.
    urgency = 1.0
    if hp <= 2.0:
        urgency = 1.15
    elif hp <= 4.0:
        urgency = 1.08
    if no_water_days >= 2:
        urgency += 0.08

    # Baseline bid: undercut the observed max pressure slightly.
    # If opponents were bidding very high, we avoid matching exactly.
    baseline = DAILY_SALARY * 0.55
    if pressure > 0:
        # Undercut by ~10% but keep above baseline.
        baseline = max(baseline, pressure * 0.90)

    target = baseline * supply_factor * urgency

    # Ensure we don't overcommit beyond a reasonable fraction of budget.
    # If budget is tight, scale down.
    max_fraction = 0.95
    if budget <= DAILY_SALARY:
        max_fraction = 0.85
    cap = budget * max_fraction

    bid = min(target, cap)

    # If hp is critically low, we must bid close to cap.
    if hp <= 1.5:
        bid = min(budget, max(bid, DAILY_SALARY * 0.9))

    # Final clamp.
    if bid < 0.0:
        bid = 0.0
    return float(bid)

